package cn.zj.zjmarket.verification;
import java.nio.file.*;
import java.math.BigDecimal;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import com.fasterxml.jackson.databind.ObjectMapper;
import static cn.zj.zjmarket.verification.SyncCommands.check;
/** Read-only, named current-batch orders; no global business recovery or raw credentials. */
final class B05Conservation {
 static void capture(JdbcTemplate db,List<String> orders,Path work,String label)throws Exception{
  check(!orders.isEmpty()&&new HashSet<>(orders).size()==orders.size(),"explicit unique owned order set");var rows=new ArrayList<Map<String,Object>>();var goods=new TreeSet<String>();BigDecimal received=BigDecimal.ZERO,refunded=BigDecimal.ZERO;
  for(String oid:orders){var row=db.queryForMap("SELECT o.order_id,o.goods_id,o.business_status,r.state AS inventory_state,p.payment_id,p.funds_state,p.amount AS payment_amount,p.success_hash,f.refund_id,f.funds_status AS refund_funds,f.release_status,f.success_hash AS refund_hash FROM b_market_order o JOIN b_inventory_reservation r ON r.order_id=o.order_id LEFT JOIN b_payment p ON p.order_id=o.order_id LEFT JOIN b_refund f ON f.order_id=o.order_id WHERE o.order_id=?",oid);goods.add(row.get("goods_id").toString());String state=row.get("inventory_state").toString();long reserve=count(db,oid,"RESERVE"),release=count(db,oid,"RELEASE"),confirm=count(db,oid,"CONFIRM");check(reserve==1&&release==(state.equals("RELEASED")?1:0)&&confirm==(state.equals("CONFIRMED")?1:0),"one reservation and exactly matching terminal ledger "+oid);row.put("reserveLedgerCount",reserve);row.put("releaseLedgerCount",release);row.put("confirmLedgerCount",confirm);
   BigDecimal paid="SUCCEEDED".equals(row.get("funds_state"))?(BigDecimal)row.get("payment_amount"):BigDecimal.ZERO;BigDecimal back=BigDecimal.ZERO;if(row.get("payment_id")!=null){var rs=db.queryForList("SELECT refunded_amount,amount,success_attempt_id FROM b_sim_refund WHERE payment_id=?",row.get("payment_id"));check(rs.size()<=1,"one channel refund root");if(!rs.isEmpty())back=(BigDecimal)rs.getFirst().get("refunded_amount");check(back.compareTo(paid)<=0,"refunded amount never exceeds original received");long successes=db.queryForObject("SELECT COUNT(*) FROM b_sim_refund_attempt a JOIN b_sim_refund r ON r.refund_id=a.refund_id WHERE r.payment_id=? AND a.state='SUCCEEDED'",Long.class,row.get("payment_id"));check(successes<=1,"at most one successful channel refund");if("SUCCEEDED".equals(row.get("refund_funds")))check(back.compareTo(paid)==0&&paid.signum()>0&&successes==1&&row.get("refund_hash")!=null,"market full-refund matches independent channel");}
   row.put("received",paid.toPlainString());row.put("channelRefunded",back.toPlainString());row.put("retained",paid.subtract(back).toPlainString());received=received.add(paid);refunded=refunded.add(back);rows.add(row);
  }
  var stocks=new ArrayList<Map<String,Object>>();for(String gid:goods){var a=db.queryForMap("SELECT available,reserved,sold FROM b_inventory_account WHERE goods_id=?",gid);var l=db.queryForMap("SELECT COALESCE(SUM(after_available-before_available),0) AS available,COALESCE(SUM(after_reserved-before_reserved),0) AS reserved,COALESCE(SUM(after_sold-before_sold),0) AS sold FROM b_inventory_ledger WHERE goods_id=?",gid);for(String k:List.of("available","reserved","sold"))check(((Number)a.get(k)).longValue()==((Number)l.get(k)).longValue(),"account equals all committed ledger deltas "+gid+"/"+k);var st=new LinkedHashMap<String,Object>();st.put("goodsId",gid);st.put("account",a);st.put("ledgerDeltas",l);stocks.add(st);}
  var result=new LinkedHashMap<String,Object>();result.put("status","PASSED");result.put("scope","explicit current-batch orders and their complete goods ledgers; read-only");result.put("orders",rows);result.put("stocks",stocks);result.put("received",received.toPlainString());result.put("refunded",refunded.toPlainString());result.put("retained",received.subtract(refunded).toPlainString());Files.writeString(work.resolve(label+"-conservation.json"),new ObjectMapper().writeValueAsString(result));
 }
 private static long count(JdbcTemplate db,String oid,String kind){return db.queryForObject("SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind=?",Long.class,oid,kind);}
}
